import sys
input = sys.stdin.readline
(n, q) = map(int, input().split())
pfactors = []
num = n
i = 2
while i * i <= num:
	if num % i == 0:
		num //= i
		pfactors.append(i)
	else:
		i += 1
if num != 1:
	pfactors.append(num)
nd = dict()
kd = dict()
for i in pfactors:
	nd[i] = 0
	kd[i] = 0
for i in pfactors:
	nd[i] += 1
for _ in range(q):
	(t, k) = map(int, input().split())
	if t == 1:
		if n == 1:
			print(1)
		elif k == 1:
			print(1)
		else:
			for i in pfactors:
				if k % i == 0:
					kd[i] += 1
					k //= i
			ans = 1
			for i in kd:
				ans *= kd[i] + 1
			print(ans)
			for i in kd:
				kd[i] = 0
	elif t == 2:
		if n == 1:
			if k == 1:
				print(1)
			else:
				print(0)
		elif k == 1:
			ans = 1
			for i in nd:
				ans *= nd[i] + 1
			print(ans)
		elif n % k != 0:
			print(0)
		else:
			for i in nd:
				kd[i] = nd[i]
			for i in pfactors:
				if k % i == 0:
					kd[i] -= 1
					k //= i
			ans = 1
			for i in kd:
				ans *= kd[i] + 1
			print(ans)
			for i in kd:
				kd[i] = 0
	elif n == 1:
		if k == 1:
			print(0)
		else:
			print(1)
	elif k == 1:
		print(0)
	elif n % k != 0:
		ans = 1
		for i in nd:
			ans *= nd[i] + 1
		print(ans)
	else:
		ans1 = 1
		for i in nd:
			ans1 *= nd[i] + 1
		for i in nd:
			kd[i] = nd[i]
		for i in pfactors:
			if k % i == 0:
				kd[i] -= 1
				k //= i
		ans2 = 1
		for i in kd:
			ans2 *= kd[i] + 1
		print(ans1 - ans2)
		for i in kd:
			kd[i] = 0
